            }
            sb.append('\n');
        }
        for (int i = 0; i < 4; i++) {
            if (header.getOpcode() != Opcode.UPDATE) {
                sb.append(";; ").append(Section.longString(i)).append(":\n");
            } else {
                sb.append(";; ").append(Section.updString(i)).append(":\n");
            }
            sectionToString(sb, i);
            sb.append("\n");
        }
        sb.append(";; Message size: ").append(numBytes()).append(" bytes");
